/opt/homebrew/bin/zsh -lc "python3 -B -c 'import json,pathlib; root=pathlib.Path(\"poc/data/clean-unlisted-probe-2026-11-16\");
for arm in (\"control\",\"changed\"):
 for n in (1,2,3):
  p=root/arm/f\"send-{n}\"/\"outcomes.jsonl\"
  for line in p.read_text().splitlines():
   r=json.loads(line)
   if \"fortnight:c1/clean-13\" in r[\"case\"] or \"july:c3/clean-7\" in r[\"case\"]: print(arm,n,r[\"case\"],r[\"status\"],\"reason\",r[\"reason\"],\"req-results\",[(q.get(\"result\"),q.get(\"reasons\")) for q in r[\"requests\"]])'"

