/opt/homebrew/bin/zsh -lc "python3 -B -c 'import json,pathlib,collections; p=pathlib.Path(\"poc/data/clean-unlisted-probe-2026-11-16/reading\");
for f in sorted((p/\"readers\").glob(\"packet-*.json\")):
 for row in json.loads(f.read_text()):
  l=row.get(\"ladder_as_the_judge_is_shown_it\",{}); d=l.get(\"no_ladder\",\"\");
  if \"Q4 2026 through calendar 2027\" in d or \"commodity DRAM and graphics\" in d:
   print(\"item\",row[\"item\"],\"file\",f.name,\"decline\",d)
   for rf in sorted((p/\"readers-answers\").glob(\"reader-*-packet-*.jsonl\")):
    for line in rf.read_text().splitlines():
     try: x=json.loads(line)
     except ValueError: continue
     if x.get(\"item\")==row[\"item\"]: print(rf.name,\"N\",x.get(\"N\"),\"why\",x.get(\"why\"))
a={};
for fam in (\"codex\",\"claude\"):
 f=p/\"third-reader\"/f\"h-rulings-{fam}-1.jsonl\"; a[fam]={x[\"id\"]:x[\"ruling\"] for x in map(json.loads,f.read_text().splitlines())}
print(\"H\",len(a[\"codex\"]),len(a[\"claude\"]),\"pairs\",collections.Counter((a[\"codex\"].get(k),a[\"claude\"].get(k)) for k in a[\"codex\"].keys()|a[\"claude\"].keys()))'"

